404	<script>
405	(function(){
406	  "use strict";
407	
408	  var CATEGORY_VAR = {
409	    "Anomaly": "--series-anomaly",
410	    "Rare Event": "--series-rare",
411	    "Communication Gap": "--series-gap"
412	  };
413	  var CATEGORY_DEF = {
414	    "Anomaly": "A genuine fault or malfunction.",
415	    "Rare Event": "Expected/planned, not a fault (manoeuvre, reset, calibration).",
416	    "Communication Gap": "Missing telemetry, not a signal anomaly."
417	  };
418	
419	  function seriesColor(name){
420	    return getComputedStyle(document.documentElement).getPropertyValue(CATEGORY_VAR[name]).trim();
421	  }
422	
423	  function fmtDate(ms){
424	    var d = new Date(ms);
425	    return d.toLocaleDateString("en-GB", { year: "numeric", month: "short", day: "2-digit", timeZone: "UTC" }) +
426	      " " + d.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit", timeZone: "UTC", hour12: false }) + " UTC";
427	  }
428	
429	  function fmtDuration(ms){
430	    var totalMin = Math.round(ms / 60000);
431	    if (totalMin < 1) return "< 1 min";
432	    if (totalMin < 60) return totalMin + " min";
433	    var totalHr = totalMin / 60;
434	    if (totalHr < 48) return (Math.round(totalHr * 10) / 10) + " h";
435	    var days = totalHr / 24;
436	    return (Math.round(days * 10) / 10) + " d";
437	  }
438	
439	  function svgEl(tag, attrs){
440	    var el = document.createElementNS("http://www.w3.org/2000/svg", tag);
441	    for (var k in attrs) el.setAttribute(k, attrs[k]);
442	    return el;
443	  }
444	
445	  fetch("data.json").then(function(r){ return r.json(); }).then(function(data){
446	    render(data);
447	  });
448	
449	  function render(data){
450	    var channels = data.channels;
451	    var categories = data.categories;
452	    var spans = data.spans; // [chIdx, catIdx, startMs, endMs, id]
453	
454	    // ---- stats ----
455	    var ids = {};
456	    var minStart = Infinity, maxEnd = -Infinity;
457	    var catCounts = {};
458	    categories.forEach(function(c){ catCounts[c] = 0; });
459	    spans.forEach(function(s){
460	      ids[s[4]] = true;
461	      if (s[2] < minStart) minStart = s[2];
462	      if (s[3] > maxEnd) maxEnd = s[3];
463	      catCounts[categories[s[1]]]++;
464	    });
465	    document.getElementById("stat-spans").textContent = spans.length.toLocaleString("en-US");
466	    document.getElementById("stat-events").textContent = Object.keys(ids).length.toLocaleString("en-US");
467	    var startYear = new Date(minStart).getUTCFullYear();
468	    var endYear = new Date(maxEnd).getUTCFullYear();
469	    document.getElementById("stat-range").textContent = startYear + "–" + endYear;
470	    var years = ((maxEnd - minStart) / (365.25 * 86400000)).toFixed(1);
471	    document.getElementById("stat-range-sub").textContent = years + " years";
472	
473	    // ---- legend ----
474	    var legend = document.getElementById("legend");
475	    categories.forEach(function(cat){
476	      var item = document.createElement("div");
477	      item.className = "legend-item";
478	      var swatch = document.createElement("span");
479	      swatch.className = "legend-swatch";
480	      swatch.style.background = seriesColor(cat);
481	      var textWrap = document.createElement("span");
482	      var name = document.createElement("span");
483	      name.className = "lname";
484	      name.textContent = cat;
485	      var count = document.createElement("span");
486	      count.className = "lcount";
487	      count.textContent = " · " + catCounts[cat].toLocaleString("en-US");
488	      var def = document.createElement("span");
489	      def.className = "ldef";
490	      def.textContent = CATEGORY_DEF[cat];
491	      textWrap.appendChild(name);
492	      textWrap.appendChild(count);
493	      textWrap.appendChild(def);
494	      item.appendChild(swatch);
495	      item.appendChild(textWrap);
496	      legend.appendChild(item);
497	    });
498	
499	    // ---- chart geometry ----
500	    var W = 1180, labelW = 96, padRight = 16, topPad = 14, rowH = 42, rowGap = 4;
501	    var plotX0 = labelW, plotX1 = W - padRight;
502	    var plotW = plotX1 - plotX0;
503	    var nRows = channels.length;
504	    var chartH = topPad + nRows * (rowH + rowGap) + 26;
505	    var svg = document.getElementById("chart");
506	    svg.setAttribute("viewBox", "0 0 " + W + " " + chartH);
507	
508	    var domainStart = Date.UTC(startYear, 0, 1);
509	    var domainEnd = Date.UTC(endYear + 1, 0, 1);
510	    function x(ms){ return plotX0 + (ms - domainStart) / (domainEnd - domainStart) * plotW; }
511	
512	    // year gridlines
513	    for (var y = startYear; y <= endYear + 1; y++){
514	      var gx = x(Date.UTC(y, 0, 1));
515	      svg.appendChild(svgEl("line", {
516	        class: "gridline", x1: gx, x2: gx,
517	        y1: topPad, y2: topPad + nRows * (rowH + rowGap) - rowGap
518	      }));
519	      if (y <= endYear){
520	        var lbl = svgEl("text", {
521	          class: "tick-label", x: gx + 3,
522	          y: topPad + nRows * (rowH + rowGap) - rowGap + 16
523	        });
524	        lbl.textContent = y;
525	        svg.appendChild(lbl);
526	      }
527	    }
528	
529	    // rows
530	    var minPxWidth = 2.4;
531	    channels.forEach(function(ch, rowIdx){
532	      var rowY = topPad + rowIdx * (rowH + rowGap);
533	      var midY = rowY + rowH / 2;
534	
535	      svg.appendChild(svgEl("line", {
536	        class: "baseline", x1: plotX0, x2: plotX1, y1: midY, y2: midY
537	      }));
538	
539	      var label = svgEl("text", {
540	        class: "row-label", x: 0, y: midY + 4
541	      });
542	      label.textContent = ch;
543	      svg.appendChild(label);
544	    });
545	
546	    spans.forEach(function(s, i){
547	      var chIdx = s[0], catIdx = s[1], startMs = s[2], endMs = s[3], id = s[4];
548	      var cat = categories[catIdx];
549	      var rowY = topPad + chIdx * (rowH + rowGap);
550	      var midY = rowY + rowH / 2;
551	      var x0 = x(startMs);
552	      var x1 = Math.max(x(endMs), x0 + minPxWidth);
553	      var rect = svgEl("rect", {
554	        class: "span-mark",
555	        x: x0, y: midY - 5, width: (x1 - x0), height: 10, rx: 2,
556	        fill: seriesColor(cat),
557	        "data-idx": i
558	      });
559	      svg.appendChild(rect);
560	    });
561	
562	    // ---- tooltip ----
563	    var tooltip = document.getElementById("tooltip");
564	    var activeEl = null;
565	
566	    function showTooltip(idx, clientX, clientY){
567	      var s = spans[idx];
568	      var cat = categories[s[1]];
569	      tooltip.innerHTML = "";
570	      var head = document.createElement("div");
571	      head.className = "tt-cat";
572	      var key = document.createElement("span");
573	      key.className = "tt-key";
574	      key.style.background = seriesColor(cat);
575	      var catText = document.createElement("span");
576	      catText.textContent = cat;
577	      head.appendChild(key);
578	      head.appendChild(catText);
579	      tooltip.appendChild(head);
580	
581	      var rows = [
582	        ["Channel", channels[s[0]]],
583	        ["Event", s[4]],
584	        ["Start", fmtDate(s[2])],
585	        ["End", fmtDate(s[3])],
586	        ["Duration", fmtDuration(s[3] - s[2])]
587	      ];
588	      rows.forEach(function(r){
589	        var row = document.createElement("div");
590	        row.className = "tt-row";
591	        var k = document.createElement("span");
592	        k.textContent = r[0];
593	        var v = document.createElement("span");
594	        v.className = "mono";
595	        v.textContent = r[1];
596	        row.appendChild(k);
597	        row.appendChild(v);
598	        tooltip.appendChild(row);
599	      });
600	
601	      var tw = 260, th = 150;
602	      var left = clientX + 14;
603	      var top = clientY + 14;
604	      if (left + tw > window.innerWidth) left = clientX - tw - 14;
605	      if (top + th > window.innerHeight) top = clientY - th - 14;
606	      tooltip.style.left = left + "px";
607	      tooltip.style.top = top + "px";
608	      tooltip.classList.add("visible");
609	    }
610	
611	    function hideTooltip(){
612	      tooltip.classList.remove("visible");
613	      if (activeEl) activeEl.classList.remove("is-active");
614	      activeEl = null;
615	    }
616	
617	    svg.addEventListener("pointermove", function(e){
618	      var t = e.target;
619	      if (t && t.classList && t.classList.contains("span-mark")){
620	        if (activeEl !== t){
621	          if (activeEl) activeEl.classList.remove("is-active");
622	          t.classList.add("is-active");
623	          activeEl = t;
624	        }
625	        showTooltip(parseInt(t.getAttribute("data-idx"), 10), e.clientX, e.clientY);
626	      } else if (activeEl){
627	        hideTooltip();
628	      }
629	    });
630	    svg.addEventListener("pointerleave", hideTooltip);
631	
632	    // ---- table ----
633	    var tbody = document.getElementById("table-body");
634	    var tableBuilt = false;
635	    document.getElementById("table-toggle").addEventListener("toggle", function(e){
636	      if (e.target.open && !tableBuilt){
637	        buildTable();
638	        tableBuilt = true;
639	      }
640	    });
641	
642	    function buildTable(){
643	      var sorted = spans.map(function(s, i){ return i; });
644	      sorted.sort(function(a, b){
645	        if (spans[a][0] !== spans[b][0]) return spans[a][0] - spans[b][0];
646	        return spans[a][2] - spans[b][2];
647	      });
648	      var frag = document.createDocumentFragment();
649	      sorted.forEach(function(i){
650	        var s = spans[i];
651	        var cat = categories[s[1]];
652	        var tr = document.createElement("tr");
653	
654	        var tdCh = document.createElement("td");
655	        tdCh.className = "mono";
656	        tdCh.textContent = channels[s[0]];
657	        tr.appendChild(tdCh);
658	
659	        var tdCat = document.createElement("td");
660	        var key = document.createElement("span");
661	        key.className = "cat-key";
662	        key.style.background = seriesColor(cat);
663	        tdCat.appendChild(key);
664	        tdCat.appendChild(document.createTextNode(cat));
665	        tr.appendChild(tdCat);
666	
667	        var tdId = document.createElement("td");
668	        tdId.className = "mono";
669	        tdId.textContent = s[4];
670	        tr.appendChild(tdId);
671	
672	        var tdStart = document.createElement("td");
673	        tdStart.className = "date";
674	        tdStart.textContent = fmtDate(s[2]);
675	        tr.appendChild(tdStart);
676	
677	        var tdEnd = document.createElement("td");
678	        tdEnd.className = "date";
679	        tdEnd.textContent = fmtDate(s[3]);
680	        tr.appendChild(tdEnd);
681	
682	        var tdDur = document.createElement("td");
683	        tdDur.className = "num";
684	        tdDur.textContent = fmtDuration(s[3] - s[2]);
685	        tr.appendChild(tdDur);
686	
687	        frag.appendChild(tr);
688	      });
689	      tbody.appendChild(frag);
690	    }
691	  }
692	})();
693	</script>
