// ---- chart geometry ----
var W = 1180, labelW = 96, padRight = 44, topPad = 14, rowH = 80, rowGap = 10;
var plotX0 = labelW, plotX1 = W - padRight;
var plotW = plotX1 - plotX0;
var nRows = channels.length;
var bandInset = 10;      // vertical inset of the value band within each row
var chartH = topPad + nRows * (rowH + rowGap) - rowGap + 26;
var svg = document.getElementById("chart");
svg.setAttribute("viewBox", "0 0 " + W + " " + chartH);

var domainStart = Date.UTC(startYear, 0, 1);
var domainEnd = Date.UTC(endYear + 1, 0, 1);
function x(ms){ return plotX0 + (ms - domainStart) / (domainEnd - domainStart) * plotW; }

var plotBottom = topPad + nRows * (rowH + rowGap) - rowGap;

// year gridlines
for (var y = startYear; y <= endYear + 1; y++){
  var gx = x(Date.UTC(y, 0, 1));
  svg.appendChild(svgEl("line", {
    class: "gridline", x1: gx, x2: gx, y1: topPad, y2: plotBottom
  }));
  if (y <= endYear){
    var lbl = svgEl("text", {
      class: "tick-label", x: gx + 3, y: plotBottom + 16
    });
    lbl.textContent = y;
    svg.appendChild(lbl);
  }
}

// ---- value envelopes + rows ----
var day0 = valueData.day0_ms, dayStep = valueData.day_step_ms, nDays = valueData.n_days;
var minPxWidth = 2.4;

channels.forEach(function(ch, rowIdx){
  var rowY = topPad + rowIdx * (rowH + rowGap);
  var bandTop = rowY + bandInset;
  var bandBottom = rowY + rowH - bandInset;
  var bandH = bandBottom - bandTop;

  if (rowIdx > 0){
    svg.appendChild(svgEl("line", {
      class: "row-sep", x1: 0, x2: plotX1, y1: rowY - rowGap / 2, y2: rowY - rowGap / 2
    }));
  }

  var label = svgEl("text", { class: "row-label", x: 0, y: rowY + 13 });
  label.textContent = ch;
  svg.appendChild(label);

  // per-channel y-domain from its own daily min/max (own scale; channels aren't comparable)
  var mins = valueData.series[ch].min, maxs = valueData.series[ch].max;
  var vMin = Infinity, vMax = -Infinity;
  for (var d = 0; d < nDays; d++){
    if (mins[d] !== null && mins[d] < vMin) vMin = mins[d];
    if (maxs[d] !== null && maxs[d] > vMax) vMax = maxs[d];
  }
  var pad = (vMax - vMin) * 0.08 || 1;
  vMin -= pad; vMax += pad;
  function vy(v){ return bandBottom - (v - vMin) / (vMax - vMin) * bandH; }

  // build min/max band as one or more segments, breaking at data gaps
  var segTop = [], segBottom = [];
  function flushSegment(){
    if (segTop.length < 2) { segTop = []; segBottom = []; return; }
    var d0 = "M " + segTop.map(function(p){ return p[0] + " " + p[1]; }).join(" L ");
    var d1 = " L " + segBottom.slice().reverse().map(function(p){ return p[0] + " " + p[1]; }).join(" L ") + " Z";
    svg.appendChild(svgEl("path", { class: "value-band", d: d0 + d1 }));
    segTop = []; segBottom = [];
  }
  for (var d = 0; d < nDays; d++){
    if (mins[d] === null){ flushSegment(); continue; }
    var px = x(day0 + d * dayStep);
    segTop.push([px, vy(maxs[d])]);
    segBottom.push([px, vy(mins[d])]);
  }
  flushSegment();

  // range label at the right of the row
  var rangeLbl = svgEl("text", {
    class: "row-range", x: plotX1 + 6, y: rowY + bandInset + 4
  });
  rangeLbl.textContent = vMax.toFixed(2);
  svg.appendChild(rangeLbl);
  var rangeLbl2 = svgEl("text", {
    class: "row-range", x: plotX1 + 6, y: bandBottom + 2
  });
  rangeLbl2.textContent = vMin.toFixed(2);
  svg.appendChild(rangeLbl2);
});

// ---- labeled spans, drawn as highlight bands over the value trace ----
spans.forEach(function(s, i){
  var chIdx = s[0], catIdx = s[1], startMs = s[2], endMs = s[3];
  var cat = categories[catIdx];
  var rowY = topPad + chIdx * (rowH + rowGap);
  var x0 = x(startMs);
  var x1 = Math.max(x(endMs), x0 + minPxWidth);
  var rect = svgEl("rect", {
    class: "span-mark",
    x: x0, y: rowY, width: (x1 - x0), height: rowH,
    fill: seriesColor(cat),
    "fill-opacity": 0.30,
    "data-idx": i
  });
  svg.appendChild(rect);
});

