515	      item.appendChild(textWrap);
516	      legend.appendChild(item);
517	    });
518	
519	    // ---- chart geometry ----
520	    var W = 1180, labelW = 96, padRight = 44, topPad = 14, rowH = 80, rowGap = 10;
521	    var plotX0 = labelW, plotX1 = W - padRight;
522	    var plotW = plotX1 - plotX0;
523	    var nRows = channels.length;
524	    var bandInset = 10;      // vertical inset of the value band within each row
525	    var chartH = topPad + nRows * (rowH + rowGap) - rowGap + 26;
526	    var svg = document.getElementById("chart");
