528	
529	    var domainStart = Date.UTC(startYear, 0, 1);
530	    var domainEnd = Date.UTC(endYear + 1, 0, 1);
531	    function x(ms){ return plotX0 + (ms - domainStart) / (domainEnd - domainStart) * plotW; }
532	
533	    var plotBottom = topPad + nRows * (rowH + rowGap) - rowGap;
534	
535	    // year gridlines
536	    for (var y = startYear; y <= endYear + 1; y++){
537	      var gx = x(Date.UTC(y, 0, 1));
538	      svg.appendChild(svgEl("line", {
539	        class: "gridline", x1: gx, x2: gx, y1: topPad, y2: plotBottom
540	      }));
541	      if (y <= endYear){
