552	    var minPxWidth = 2.4;
553	
554	    channels.forEach(function(ch, rowIdx){
555	      var rowY = topPad + rowIdx * (rowH + rowGap);
556	      var bandTop = rowY + bandInset;
557	      var bandBottom = rowY + rowH - bandInset;
558	      var bandH = bandBottom - bandTop;
559	
560	      if (rowIdx > 0){
